function customerAppointmentSnapshot(snapshot, business) {
  snapshot = snapshot || {};
  const appointments = (snapshot.appointments || []).map(function (row) {
    const statusMap = { booked: "confirmed", rescheduled: "confirmed", requested: "ai_confirming", failed: "needs_you", cancelled: "cancelled" };
    return Object.assign({}, row, {
      id: row.conversation_id,
      ui_status: statusMap[row.status] || "ai_confirming",
      duration_minutes: Number(row.duration_minutes) || 60,
      initials: String(row.customer_name || "Cliente").split(/\s+/).slice(0, 2).map(function (part) { return part.charAt(0); }).join("").toUpperCase(),
      sync: row.sync || (row.calendar_sync_status === "synced" ? "synced" : "pending"),
      alt_slots: row.alt_slots || []
    });
  });
  return {
    ok: true,
    tenant_id: snapshot.tenant_id,
    business: business || null,
    source: snapshot.source || "memory",
    provider: { id: "google_calendar", label: "Google Calendar", status: "available" },
    metrics: Object.assign({ confirmation_rate: 0, avoided_absences: 0, sent_reminders: 0 }, snapshot.metrics || {}),
    appointments: appointments,
    reminders: snapshot.reminders || []
  };
}

