function appointmentRuleValue(value){if(value===true)return "Sí";if(value===false)return "No";var labels={one:"Una persona",multiple:"Varias personas",depends:"Depende del servicio",automatic:"Automática",manual_approval:"Requiere aprobación",whatsapp:"WhatsApp",email:"Correo",sms:"SMS",none:"No configurado",both:"24 y 6 horas antes","24h":"24 horas antes","6h":"6 horas antes","2h":"2 horas antes",custom:"Horario personalizado",google:"Google Calendar",microsoft:"Microsoft Outlook"};return labels[String(value)]||String(value||"").trim();}
