function renderAppointmentRules(){var root=document.getElementById("apptRulesContent"),payload=state.appointmentOnboarding||{},record=payload.onboarding||{},answers=record.answers||{},setup=answers.appointment_setup||{};if(!root)return;var groups=[appointmentRuleGroup("◷","Agenda y disponibilidad","Cuándo y dónde puede reservar la IA",[["Horario general",setup.business_hours],["Quién atiende",setup.staff_mode],["Ubicaciones",setup.appointment_locations],["Disponibilidad",setup.availability_rules]]),appointmentRuleGroup("✓","Reglas de reserva","Qué necesita confirmar antes de crear una cita",[["Servicios",setup.services],["Datos requeridos",setup.required_booking_fields],["Modo de confirmación",setup.booking_confirmation_mode],["Cancelaciones y cambios",setup.cancellation_policy]]),appointmentRuleGroup("↻","Seguimiento","Cómo quedó configurado el acompañamiento",[["Canal de recordatorio",setup.reminder_channel],["Momento del recordatorio",setup.reminder_timing],["Encuesta posterior",setup.survey_enabled],["Apoyo humano",setup.escalation_contact]]),appointmentRuleGroup("▦","Canales y calendario","Conexiones elegidas durante el setup",[["Calendario",setup.calendar_provider],["Correo de citas",setup.calendar_email||setup.channel_email],["Canales operativos",setup.operational_channels],["Llamadas",setup.calls_enabled]])].filter(Boolean);root.innerHTML=groups.join("")||'<div class="apptRuleEmpty"><strong>Aún no hay reglas de agendamiento guardadas.</strong>Abre el setup para completar la información que utilizará tu bot.</div>';}
function loadAppointmentRules(){var root=document.getElementById("apptRulesContent");if(state.appointmentOnboarding){renderAppointmentRules();return;}if(DEMO_MODE){state.appointmentOnboarding={onboarding:{answers:{appointment_setup:{business_hours:"Lunes a viernes · 8:00 a. m. a 6:00 p. m.",staff_mode:"multiple",appointment_locations:"Sede principal y videollamada",availability_rules:"La disponibilidad se valida contra el calendario conectado.",services:"Consulta inicial, seguimiento y valoración",required_booking_fields:"Nombre, teléfono, servicio y horario preferido",booking_confirmation_mode:"manual_approval",cancellation_policy:"Cambios con mínimo 12 horas de anticipación.",reminder_channel:"whatsapp",reminder_timing:"both",survey_enabled:"yes",escalation_contact:"Recepción",calendar_provider:"google",channel_email:"citas@comerciopiloto.co",operational_channels:"WhatsApp y llamadas",calls_enabled:"yes"}}}};renderAppointmentRules();return;}if(root)root.innerHTML='<div class="apptRuleEmpty"><strong>Cargando tu configuración…</strong>Consultando el registro de tu empresa.</div>';api(PANEL_ONBOARDING_PATH,{redirectOnAuth:true}).then(function(data){state.appointmentOnboarding=data;renderAppointmentRules();}).catch(function(error){if(root)root.innerHTML='<div class="apptRuleEmpty"><strong>No pudimos cargar tu configuración.</strong>'+esc(error.body&&error.body.message||"Intenta nuevamente o abre el setup para revisarla.")+'</div>';});}
function openAppointmentReprogram(){var rows=appointmentRowsInSelectedWeek(),box=document.getElementById("apptDayChoices");box.innerHTML=APPT_DAYS.slice(0,5).map(function(day,index){var count=rows.filter(function(row){return apptDayIndex(row)===index&&apptStatus(row)!=="cancelled";}).length;return '<button type="button" data-day="'+index+'" onclick="chooseReprogramDay('+index+')">'+day+'<br><small>'+count+(count===1?' cita':' citas')+'</small></button>';}).join("");state.reprogramDay=0;chooseReprogramDay(0);document.getElementById("apptReprogramModal").classList.add("open");}
function chooseReprogramDay(day){state.reprogramDay=day;document.querySelectorAll("[data-day]").forEach(function(button){button.classList.toggle("active",Number(button.getAttribute("data-day"))===day);});var rows=appointmentRowsInSelectedWeek().filter(function(row){return apptDayIndex(row)===day&&apptStatus(row)!=="cancelled";}),preview=document.getElementById("apptReprogramPreview"),button=document.getElementById("apptReprogramConfirm");preview.innerHTML=rows.length?'<strong>'+rows.length+(rows.length===1?' paciente':' pacientes')+'</strong><br>Se guardará una solicitud de reprogramación con disculpa y seguimiento pendiente.':'Este día está libre. No hay citas para reprogramar.';button.disabled=!rows.length;button.textContent='Reprogramar '+rows.length+(rows.length===1?' cita':' citas');}
function closeAppointmentReprogram(){document.getElementById("apptReprogramModal").classList.remove("open");}
function confirmAppointmentReprogram(){var day=state.reprogramDay,rows=appointmentRowsInSelectedWeek().filter(function(row){return apptDayIndex(row)===day&&apptStatus(row)!=="cancelled";}),ids=rows.map(function(row){return row.id||row.conversation_id;});closeAppointmentReprogram();appointmentAction("reprogram",ids,{reason:"Bloqueo de agenda desde el panel",message:"El usuario Nextfor solicitó reprogramar estas citas y ofrecer disculpas."},"Reprogramación guardada para seguimiento ✓");}
function appointmentToast(message){var toast=document.getElementById("apptToast");toast.textContent=message;toast.classList.add("show");setTimeout(function(){toast.classList.remove("show");},2600);}
